/**
 * M08-2 condition — real Chromium parse → claim → toggle → dispose vertical.
 *
 * The server string is generated by `__ssr` (Node side), the browser parser owns
 * the nodes, and the generated claim adopts exactly those nodes. LOCAL Chromium
 * only: this is not M13 and not M08 exit.
 *
 * Covered here:
 *   - equal seed: zero claim-period mutations and branch-node identity;
 *   - false → true → false branch replacement with the anchor/end staying put;
 *   - an empty server branch: equal seed is zero-mutation, and a matching
 *     claim may insert (explicitly non-clean activation work, not 0-mutation);
 *   - server non-empty/client empty and branch-structure mismatch: fail closed,
 *     borrowed DOM untouched, no subscription opened;
 *   - a throwing branch activation: error surfaces, borrowed DOM kept, no
 *     leaked subscription;
 *   - `dispose(false)` keeps borrowed DOM and releases subscriptions,
 *     `dispose(true)` removes the whole claimed region.
 */

import { afterAll, beforeAll, describe, expect, test } from 'vitest';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { chromium, type Browser, type Page } from 'playwright';
import { build } from 'vite';
import { compileFunctionModule } from '../../src/internal/compiler/semantic-core/function-frontend.ts';
import { generateLeafModule } from '../../src/internal/compiler/semantic-ir/generated-leaf/generate.ts';
import * as compiledRuntime from '../../../element/src/internal/compiled/runtime.ts';
import { signal } from '../../../element/src/internal/signal/framework.ts';

const FILE = '/proj/src/claim-condition-browser.tsx';
const REPO_ROOT = new URL('../../../../', import.meta.url).pathname;

const CLASSIFIER = {
  classifySymbol: (specifier: string, importedName: string | null) => {
    if (specifier !== '@openelement/element') return undefined;
    if (importedName === 'signal' || importedName === 'computed') return 'factory' as const;
    return 'value' as const;
  },
  classifyValue: () => undefined,
  classifyCall: (specifier: string, importedName: string | null) => {
    if (specifier !== '@openelement/element') return undefined;
    if (importedName === 'signal') return { call: 'signal' as const };
    if (importedName === 'computed') return { call: 'computed' as const };
    return undefined;
  },
};

const SOURCE = `import { signal } from '@openelement/element';
function Panel(props) {
  const open = signal(true);
  const label = signal('open');
  return <section>
    {open.value ? <p class="on">{label.value}</p> : <em class="off">closed</em>}
    <span>after</span>
  </section>;
}
function Maybe(props) {
  const show = signal(false);
  const label = signal('shown');
  return <div>{show.value ? <p>{label.value}</p> : null}<span>after</span></div>;
}
function Throwing(props) {
  const open = signal(true);
  const boom = signal('x');
  return <div>{open.value ? <p>{boom.value}</p> : <i>safe</i>}<span>after</span></div>;
}
function Child(props) {
  return <b>child</b>;
}
function Parent(props) {
  const open = signal(true);
  return <div><Child /><span>{open.value ? <b>on</b> : <i>off</i>}</span><i>after</i></div>;
}
function StaticRun(props) {
  const open = signal(true);
  return <div>{open.value ? <><>A</>B</> : null}</div>;
}
`;

const RUNTIME = { ...compiledRuntime };
const SSR_EXPORT = /^export function ([\w$]+)\(/gm;
const RUNTIME_IMPORT = /^import \{([^}]+)\} from [^;]+;$/m;

function instantiate(module: string): Record<string, unknown> {
  const exported = [...module.matchAll(SSR_EXPORT)].map((match) => match[1]!);
  const importMatch = module.match(RUNTIME_IMPORT);
  if (importMatch === null) throw new Error('generated module has no runtime import');
  const imported = importMatch[1]!
    .split(',')
    .map((name) => name.trim())
    .filter((name) => name.length > 0);
  const body = module
    .replace(RUNTIME_IMPORT, `const { ${imported.join(', ')} } = __oe_runtime;`)
    .replace(/^export function /gm, 'function ');
  const factory = new Function(
    '__oe_runtime',
    `"use strict";\n${body}\nreturn { ${exported.join(', ')} };`,
  ) as (runtime: Record<string, unknown>) => Record<string, unknown>;
  return factory(RUNTIME);
}

interface Fixture {
  readonly module: string;
  readonly loaded: Record<string, unknown>;
}

function fixture(): Fixture {
  const front = compileFunctionModule(SOURCE, FILE, { importClassifier: CLASSIFIER });
  expect(front.diagnostics).toEqual([]);
  const generated = generateLeafModule(front.module!);
  expect(generated.diagnostics.map((item) => item.message)).toEqual([]);
  expect(generated.module).not.toBeNull();
  return { module: generated.module!, loaded: instantiate(generated.module!) };
}

type SsrFunction = (
  props?: Record<string, unknown>,
  host?: { readonly bindings: Record<string, unknown> },
) => string;

function ssr(loaded: Record<string, unknown>, name: string): SsrFunction {
  const value = loaded[`${name}__ssr`];
  if (typeof value !== 'function') throw new Error(`missing ${name}__ssr`);
  return value as SsrFunction;
}

function harnessModule(module: string): string {
  const importMatch = module.match(RUNTIME_IMPORT);
  if (importMatch === null) throw new Error('generated module has no runtime import');
  const imported = importMatch[1]!
    .split(',')
    .map((name) => name.trim())
    .filter((name) => name.length > 0);
  const names = [...module.matchAll(/^export function (create\w+Recipe)\(/gm)].map(
    (match) => match[1]!,
  );
  const body = module
    .replace(RUNTIME_IMPORT, `const { ${imported.join(', ')} } = window.__oeRuntime;`)
    .replace(/^export function /gm, 'function ');
  return `(function () {\n${body}\nwindow.__oeModule = { ${names.join(', ')} };\n})();\n`;
}

let runtimeBundle = '';
let runtimeBundleDir = '';
let browser: Browser;
let page: Page;

beforeAll(async () => {
  runtimeBundleDir = mkdtempSync(join(tmpdir(), 'oe-condition-claim-browser-'));
  const entry = join(runtimeBundleDir, 'entry.ts');
  const element = join(REPO_ROOT, 'packages/element/src/internal');
  const runtime = join(element, 'compiled/runtime');
  writeFileSync(
    entry,
    [
      `export { claimRecipe, createRecipe, insertRecipe } from ${JSON.stringify(join(runtime, 'recipe.ts'))};`,
      `export { bindSignalWrites, runUntracked } from ${JSON.stringify(join(runtime, 'bindings.ts'))};`,
      `export { attributeValueOf, assertSafeUrlAttribute, displayValue, removeNodes } from ${JSON.stringify(join(runtime, 'values.ts'))};`,
      `export { assertElementInHtmlNamespace, assertStaticAttributeSeed, assertTextSlotMarker, assertWhenAnchor, assertWhenEndMarker, isWhenEndMarker, leafClaimMismatch } from ${JSON.stringify(join(runtime, 'claim-invariants.ts'))};`,
      `export { emitComment, MARKERS, markerText, parseRangeMarker, parseTextSlotMarker, parseWhenMarker, rangeMarker, textSlotMarker } from ${JSON.stringify(join(runtime, 'markers.ts'))};`,
      `export { claimStaticSiblingRange, openStaticSiblingDirectory } from ${JSON.stringify(join(runtime, 'static-sibling-ranges.ts'))};`,
      `export { runtimeProbe } from ${JSON.stringify(join(runtime, 'observability.ts'))};`,
      `export { escapeText } from ${JSON.stringify(join(element, 'compiled/escape-text.ts'))};`,
      `export { escapeAttrValue } from ${JSON.stringify(join(element, 'core/html-escape.ts'))};`,
      `export { LifetimeScope } from ${JSON.stringify(join(element, 'compiled/lifetime-scope.ts'))};`,
      `export { computed, signal } from ${JSON.stringify(join(element, 'signal/framework.ts'))};`,
      '',
    ].join('\n'),
  );
  const result = await build({
    configFile: false,
    root: runtimeBundleDir,
    logLevel: 'silent',
    build: {
      write: false,
      minify: false,
      lib: { entry, formats: ['iife'], name: '__oeRuntime', fileName: () => 'runtime.js' },
    },
  });
  const output = Array.isArray(result)
    ? result[0]!.output
    : (result as { output: unknown[] }).output;
  const chunk = (output as Array<{ type: string; code?: string }>).find(
    (item) => item.type === 'chunk',
  );
  if (chunk?.code === undefined) throw new Error('runtime bundle produced no chunk');
  runtimeBundle = chunk.code;
  browser = await chromium.launch();
  console.log(`[M08-condition] engine=chromium version=${browser.version()} LOCAL`);
}, 120_000);

afterAll(async () => {
  await browser?.close();
  if (runtimeBundleDir !== '') rmSync(runtimeBundleDir, { recursive: true, force: true });
});

async function prepare(): Promise<Fixture> {
  const generated = fixture();
  page = await browser.newPage();
  await page.addScriptTag({ content: runtimeBundle });
  await page.addScriptTag({ content: harnessModule(generated.module) });
  return generated;
}

interface RuntimePage {
  claimRecipe(
    owner: unknown,
    recipe: unknown,
    parent: Node,
  ): {
    readonly nodes: readonly Node[];
    dispose(detach?: boolean): void;
  };
  LifetimeScope: new () => { dispose(detach?: boolean): void };
  signal<T>(value: T): { value: T };
  runtimeProbe: {
    reset(): void;
    snapshot(): {
      subscriptions: number;
      unsubscribed: number;
      owners: number;
      projections: number;
      rangeCleanups: number;
    };
  };
}

interface PageModule {
  [name: string]: (owner: unknown, host: unknown) => unknown;
}

describe('M08-2 condition — Chromium parse and claim', () => {
  test('equal seed is zero-mutation; false→true→false keeps the anchor/end and swaps only the branch', async () => {
    const generated = await prepare();
    const serverOpen = signal(true);
    const serverLabel = signal('open');
    const html = ssr(generated.loaded, 'Panel')(
      {},
      { bindings: { open: serverOpen, label: serverLabel } },
    );

    const result = (await page.evaluate(async (serverHtml) => {
      const runtime = (window as unknown as { __oeRuntime: RuntimePage }).__oeRuntime;
      const factories = (window as unknown as { __oeModule: PageModule }).__oeModule;
      document.body.innerHTML = '<div id="host"></div>';
      const host = document.getElementById('host') as HTMLElement;
      host.innerHTML = serverHtml;
      const section = host.firstChild as Element;

      const open = runtime.signal(true);
      const label = runtime.signal('open');
      let openSubs = 0;
      let openCalls = 0;
      let labelSubs = 0;
      let labelCalls = 0;
      const origOpenSub = open.subscribe.bind(open);
      open.subscribe = (fn: (value: boolean) => void) => {
        openSubs += 1;
        return origOpenSub((value) => {
          openCalls += 1;
          fn(value);
        });
      };
      const origLabelSub = label.subscribe.bind(label);
      label.subscribe = (fn: (value: string) => void) => {
        labelSubs += 1;
        return origLabelSub((value) => {
          labelCalls += 1;
          fn(value);
        });
      };
      const propsChanged = runtime.signal(0);
      const scope = new runtime.LifetimeScope();
      const recipe = factories.createPanelRecipe!(scope, {
        props: {},
        bindings: { open, label },
        propsChanged,
      });

      const mutations: string[] = [];
      const observer = new MutationObserver((records) => {
        for (const record of records) mutations.push(record.type);
      });
      observer.observe(host, {
        subtree: true,
        childList: true,
        characterData: true,
        attributes: true,
      });

      runtime.runtimeProbe.reset();
      let error: string | null = null;
      let projection: { readonly nodes: readonly Node[]; dispose(detach?: boolean): void } | null =
        null;
      try {
        projection = runtime.claimRecipe(scope, recipe, host);
      } catch (caught) {
        error = caught instanceof Error ? caught.message : String(caught);
      }
      for (const record of observer.takeRecords()) mutations.push(record.type);
      const claimMutations = mutations.length;
      const before = [...section.childNodes];
      const anchor = before[0]!;
      const end = before[2]!;
      const paragraph = before[1] as Element;
      const paragraphText = paragraph.childNodes[1] as Text;
      const identity = {
        anchorSame: section.childNodes[0] === anchor,
        endSame: section.childNodes[2] === end,
        paragraphSame: section.childNodes[1] === paragraph,
        textSame: paragraph.childNodes[1] === paragraphText,
        rootSame: projection !== null && projection.nodes[0] === section,
      };

      const afterClaim = runtime.runtimeProbe.snapshot();

      open.value = false;
      await Promise.resolve();
      await Promise.resolve();
      const offMutations = mutations.slice(claimMutations);
      const off = {
        tags: [...section.children].map((child) => child.tagName.toLowerCase()),
        anchorSame: section.childNodes[0] === anchor,
        endSame: section.childNodes[section.childNodes.length - 2] === end,
        paragraphGone: !section.contains(paragraph),
        inner: section.innerHTML,
      };

      open.value = true;
      await Promise.resolve();
      await Promise.resolve();
      const onMutations = mutations.slice(claimMutations + offMutations.length);
      const on = {
        tags: [...section.children].map((child) => child.tagName.toLowerCase()),
        anchorSame: section.childNodes[0] === anchor,
        endSame: section.childNodes[section.childNodes.length - 2] === end,
        paragraph: section.querySelector('p') as Element | null,
        inner: section.innerHTML,
      };
      const paragraphNode = on.paragraph as Element;
      label.value = 'next';
      await Promise.resolve();
      await Promise.resolve();
      const textAfter = (paragraphNode.childNodes[1] as Text).nodeValue;
      const afterUpdate = runtime.runtimeProbe.snapshot();

      observer.disconnect();
      projection?.dispose(false);
      const afterDefaultDispose = {
        hostChildren: host.childNodes.length,
        sectionStillThere: host.contains(section),
        subscriptions: runtime.runtimeProbe.snapshot().subscriptions,
        unsubscribed: runtime.runtimeProbe.snapshot().unsubscribed,
      };

      const scope2 = new runtime.LifetimeScope();
      const recipe2 = factories.createPanelRecipe!(scope2, {
        props: {},
        bindings: { open, label },
        propsChanged: runtime.signal(0),
      });
      const second = runtime.claimRecipe(scope2, recipe2, host);
      second.dispose(true);
      const afterDetachDispose = host.childNodes.length;

      return {
        error,
        claimMutations,
        identity,
        afterClaim,
        off,
        offMutations,
        on: { ...on, paragraph: undefined },
        onMutations,
        textAfter,
        afterUpdate,
        afterDefaultDispose,
        afterDetachDispose,
      };
    }, html)) as {
      error: string | null;
      claimMutations: number;
      identity: {
        anchorSame: boolean;
        endSame: boolean;
        paragraphSame: boolean;
        textSame: boolean;
        rootSame: boolean;
      };
      afterClaim: {
        subscriptions: number;
        unsubscribed: number;
        owners: number;
        projections: number;
      };
      off: {
        tags: string[];
        anchorSame: boolean;
        endSame: boolean;
        paragraphGone: boolean;
        inner: string;
      };
      offMutations: string[];
      on: { tags: string[]; anchorSame: boolean; endSame: boolean; inner: string };
      onMutations: string[];
      textAfter: string;
      afterUpdate: { subscriptions: number; unsubscribed: number };
      afterDefaultDispose: {
        hostChildren: number;
        sectionStillThere: boolean;
        subscriptions: number;
        unsubscribed: number;
      };
      afterDetachDispose: number;
    };

    expect(result.error).toBeNull();
    expect(result.claimMutations).toBe(0);
    expect(result.identity).toEqual({
      anchorSame: true,
      endSame: true,
      paragraphSame: true,
      textSame: true,
      rootSame: true,
    });
    expect(result.afterClaim.subscriptions).toBe(2);
    expect(result.afterClaim.unsubscribed).toBe(0);
    expect(result.afterClaim.projections).toBe(1);
    expect(result.off.tags).toEqual(['em', 'span']);
    expect(result.off.anchorSame).toBe(true);
    expect(result.off.endSame).toBe(true);
    expect(result.off.paragraphGone).toBe(true);
    expect(result.off.inner).toBe(
      '<!--oe:when--><em class="off">closed</em><!--oe:/when--><span>after</span>',
    );
    expect(result.offMutations).toEqual(['childList', 'childList']);
    expect(result.on.tags).toEqual(['p', 'span']);
    expect(result.on.anchorSame).toBe(true);
    expect(result.on.endSame).toBe(true);
    expect(result.on.inner).toBe(
      '<!--oe:when--><p class="on"><!--oe:t:0-->open<!--oe:/t:0--></p><!--oe:/when--><span>after</span>',
    );
    expect(result.onMutations).toEqual(['childList', 'childList']);
    expect(result.textAfter).toBe('next');
    // Probe counters are monotonic: 3 opened (open + adopted label + new
    // branch label) and 1 closed (the adopted branch's label subscription).
    expect(result.afterUpdate.subscriptions).toBe(3);
    expect(result.afterUpdate.unsubscribed).toBe(1);
    expect(result.afterDefaultDispose).toEqual({
      hostChildren: 1,
      sectionStillThere: true,
      subscriptions: 3,
      unsubscribed: 3,
    });
    expect(result.afterDetachDispose).toBe(0);
    await page.close();
  });

  test('empty branch: equal seed is zero-mutation; insert is explicit activation, then removal', async () => {
    const generated = await prepare();
    const serverShow = signal(false);
    const serverLabel = signal('shown');
    const html = ssr(generated.loaded, 'Maybe')(
      {},
      { bindings: { show: serverShow, label: serverLabel } },
    );

    const result = (await page.evaluate(async (serverHtml) => {
      const runtime = (window as unknown as { __oeRuntime: RuntimePage }).__oeRuntime;
      const factories = (window as unknown as { __oeModule: PageModule }).__oeModule;
      document.body.innerHTML = '<div id="host"></div>';
      const host = document.getElementById('host') as HTMLElement;
      host.innerHTML = serverHtml;
      const div = host.firstChild as Element;
      const show = runtime.signal(true);
      const label = runtime.signal('shown');
      const propsChanged = runtime.signal(0);
      const scope = new runtime.LifetimeScope();
      const recipe = factories.createMaybeRecipe!(scope, {
        props: {},
        bindings: { show, label },
        propsChanged,
      });
      const mutations: string[] = [];
      const observer = new MutationObserver((records) => {
        for (const record of records) mutations.push(record.type);
      });
      observer.observe(host, { subtree: true, childList: true, characterData: true });
      const anchor = div.childNodes[0]!;
      const end = div.childNodes[1]!;
      const span = div.childNodes[2]!;
      runtime.runtimeProbe.reset();
      const projection = runtime.claimRecipe(scope, recipe, host);
      for (const record of observer.takeRecords()) mutations.push(record.type);
      const claimMutations = mutations.length;
      const afterInsert = {
        childCount: div.childNodes.length,
        tags: [...div.children].map((child) => child.tagName.toLowerCase()),
        p: div.querySelector('p') as Element | null,
        anchorSame: div.childNodes[0] === anchor,
        endAfterP: div.childNodes[2] === end,
        spanAfterEnd: div.childNodes[3] === span,
        inner: div.innerHTML,
        subscriptions: runtime.runtimeProbe.snapshot().subscriptions,
      };
      show.value = false;
      await Promise.resolve();
      await Promise.resolve();
      const afterRemove = {
        childCount: div.childNodes.length,
        p: div.querySelector('p') as Element | null,
        anchorSame: div.childNodes[0] === anchor,
        endSame: div.childNodes[1] === end,
        spanSame: div.childNodes[2] === span,
        inner: div.innerHTML,
      };
      observer.disconnect();
      projection.dispose(true);
      return {
        claimMutations,
        afterInsert: { ...afterInsert, p: afterInsert.p !== null },
        afterRemove: { ...afterRemove, p: afterRemove.p !== null },
        afterDetachDispose: host.childNodes.length,
      };
    }, html)) as {
      claimMutations: number;
      afterInsert: {
        childCount: number;
        tags: string[];
        p: boolean;
        anchorSame: boolean;
        endAfterP: boolean;
        spanAfterEnd: boolean;
        inner: string;
        subscriptions: number;
      };
      afterRemove: {
        childCount: number;
        p: boolean;
        anchorSame: boolean;
        endSame: boolean;
        spanSame: boolean;
        inner: string;
      };
      afterDetachDispose: number;
    };

    // The server branch was empty but the client branch is non-empty: claim
    // succeeds through insert-only activation. This is explicitly NOT a
    // zero-mutation claim; one childList record proves the insertion.
    expect(result.claimMutations).toBe(1);
    expect(result.afterInsert.childCount).toBe(4);
    expect(result.afterInsert.tags).toEqual(['p', 'span']);
    expect(result.afterInsert.p).toBe(true);
    expect(result.afterInsert.anchorSame).toBe(true);
    expect(result.afterInsert.endAfterP).toBe(true);
    expect(result.afterInsert.spanAfterEnd).toBe(true);
    expect(result.afterInsert.inner).toBe(
      '<!--oe:when--><p><!--oe:t:0-->shown<!--oe:/t:0--></p><!--oe:/when--><span>after</span>',
    );
    // `show` + `label` are the two branch/test subscriptions after insertion.
    expect(result.afterInsert.subscriptions).toBe(2);
    expect(result.afterRemove.childCount).toBe(3);
    expect(result.afterRemove.p).toBe(false);
    expect(result.afterRemove.anchorSame).toBe(true);
    expect(result.afterRemove.endSame).toBe(true);
    expect(result.afterRemove.spanSame).toBe(true);
    expect(result.afterDetachDispose).toBe(0);
    await page.close();
  });

  test('server non-empty/client empty and branch mismatch fail closed without deleting borrowed DOM', async () => {
    const generated = await prepare();
    const serverOpenOn = signal(true);
    const serverLabelOn = signal('open');
    const panelOnHtml = ssr(generated.loaded, 'Panel')(
      {},
      { bindings: { open: serverOpenOn, label: serverLabelOn } },
    );
    const serverOpenOff = signal(false);
    const serverLabelOff = signal('open');
    const panelOffHtml = ssr(generated.loaded, 'Panel')(
      {},
      { bindings: { open: serverOpenOff, label: serverLabelOff } },
    );
    const serverShow = signal(false);
    const serverShowOn = signal(true);
    const serverLabel2 = signal('x');
    const maybeHtml = ssr(generated.loaded, 'Maybe')(
      {},
      { bindings: { show: serverShow, label: serverLabel2 } },
    );
    const maybeOnHtml = ssr(generated.loaded, 'Maybe')(
      {},
      { bindings: { show: serverShowOn, label: serverLabel2 } },
    );

    const result = (await page.evaluate(
      (args) => {
        const { panelOff, panelOn, maybe, maybeOn } = args as {
          panelOff: string;
          panelOn: string;
          maybe: string;
          maybeOn: string;
        };
        const runtime = (window as unknown as { __oeRuntime: RuntimePage }).__oeRuntime;
        const factories = (window as unknown as { __oeModule: PageModule }).__oeModule;

        const attempt = (
          serverHtml: string,
          factoryName: string,
          bindings: Record<string, unknown>,
          props: Record<string, unknown>,
        ) => {
          document.body.innerHTML = '<div id="host"></div>';
          const host = document.getElementById('host') as HTMLElement;
          host.innerHTML = serverHtml;
          const snapshot = [...host.childNodes];
          const childSnapshot = [...(host.firstChild as Element).childNodes];
          runtime.runtimeProbe.reset();
          const scope = new runtime.LifetimeScope();
          const recipe = factories[factoryName]!(scope, {
            props,
            bindings,
            propsChanged: runtime.signal(0),
          });
          let error: string | null = null;
          try {
            runtime.claimRecipe(scope, recipe, host);
          } catch (caught) {
            error = caught instanceof Error ? caught.message : String(caught);
          }
          const after = runtime.runtimeProbe.snapshot();
          const root = host.firstChild as Element;
          return {
            error,
            sameRoot: host.childNodes[0] === snapshot[0],
            sameChildren:
              root.childNodes.length === childSnapshot.length &&
              childSnapshot.every((node, index) => root.childNodes[index] === node),
            html: host.innerHTML,
            subscriptions: after.subscriptions,
            unsubscribed: after.unsubscribed,
          };
        };

        const clientEmpty = attempt(
          maybeOn,
          'createMaybeRecipe',
          {
            show: runtime.signal(false),
            label: runtime.signal('x'),
          },
          {},
        );
        const branchMismatch = attempt(
          panelOff,
          'createPanelRecipe',
          {
            open: runtime.signal(true),
            label: runtime.signal('open'),
          },
          {},
        );
        const missingEnd = attempt(
          panelOn.replace('<!--oe:/when-->', ''),
          'createPanelRecipe',
          { open: runtime.signal(true), label: runtime.signal('open') },
          {},
        );
        const emptyVsServer = attempt(
          maybe,
          'createMaybeRecipe',
          {
            show: runtime.signal(false),
            label: runtime.signal('x'),
          },
          {},
        );
        return { clientEmpty, branchMismatch, missingEnd, emptyVsServer };
      },
      { panelOff: panelOffHtml, panelOn: panelOnHtml, maybe: maybeHtml, maybeOn: maybeOnHtml },
    )) as {
      clientEmpty: {
        error: string | null;
        sameRoot: boolean;
        sameChildren: boolean;
        html: string;
        subscriptions: number;
        unsubscribed: number;
      };
      branchMismatch: {
        error: string | null;
        sameRoot: boolean;
        sameChildren: boolean;
        html: string;
        subscriptions: number;
        unsubscribed: number;
      };
      missingEnd: {
        error: string | null;
        sameRoot: boolean;
        sameChildren: boolean;
        html: string;
        subscriptions: number;
        unsubscribed: number;
      };
      emptyVsServer: {
        error: string | null;
        sameRoot: boolean;
        sameChildren: boolean;
        html: string;
        subscriptions: number;
        unsubscribed: number;
      };
    };

    expect(result.clientEmpty.error).toContain('condition end');
    expect(result.clientEmpty.sameRoot).toBe(true);
    expect(result.clientEmpty.sameChildren).toBe(true);
    expect(result.clientEmpty.html).toContain('<p><!--oe:t:0-->x');
    expect(result.clientEmpty.subscriptions).toBe(0);
    expect(result.clientEmpty.unsubscribed).toBe(0);

    // The client branch is `p`, the server branch is `em`: mismatch without
    // replacing the borrowed branch.
    expect(result.branchMismatch.error).toContain("expected element 'p'");
    expect(result.branchMismatch.sameRoot).toBe(true);
    expect(result.branchMismatch.sameChildren).toBe(true);
    expect(result.branchMismatch.html).toContain('<em class="off">closed</em>');
    expect(result.branchMismatch.subscriptions).toBe(0);

    // A stripped `oe:/when` is a condition-end mismatch; the borrowed branch is
    // left untouched and no subscription is opened.
    expect(result.missingEnd.error).toContain('condition end');
    expect(result.missingEnd.sameChildren).toBe(true);
    expect(result.missingEnd.html).toContain('<p class="on">');
    expect(result.missingEnd.subscriptions).toBe(0);

    // Server branch empty, client empty: equal seed, no insert.
    expect(result.emptyVsServer.error).toBeNull();
    expect(result.emptyVsServer.sameChildren).toBe(true);
    expect(result.emptyVsServer.html).toBe(
      '<div><!--oe:when--><!--oe:/when--><span>after</span></div>',
    );
    await page.close();
  });

  test('mount-created branch subscriptions stay isolated from the condition test', async () => {
    await prepare();
    const mountedAfter = await page.evaluate(async () => {
      const runtime = (window as unknown as { __oeRuntime: RuntimePage }).__oeRuntime;
      const factories = (window as unknown as { __oeModule: PageModule }).__oeModule;
      document.body.innerHTML = '<div id="host"></div>';
      const host = document.getElementById('host') as HTMLElement;
      const open = runtime.signal(true);
      const label = runtime.signal('open');
      const scope = new runtime.LifetimeScope();
      const recipe = factories.createPanelRecipe!(scope, {
        props: {},
        bindings: { open, label },
        propsChanged: runtime.signal(0),
      });
      const mounted = (recipe as { mount(scope: unknown): Node[] }).mount(scope);
      host.append(...mounted);
      const section = host.firstChild as Element;

      open.value = false;
      await Promise.resolve();
      await Promise.resolve();
      open.value = true;
      await Promise.resolve();
      await Promise.resolve();
      const paragraph = section.querySelector('p') as Element;
      const text = paragraph.childNodes[1] as Text;
      label.value = 'next';
      await Promise.resolve();
      await Promise.resolve();
      const after = {
        sameParagraph: section.querySelector('p') === paragraph,
        sameText: paragraph.childNodes[1] === text,
        text: text.nodeValue,
        inner: section.innerHTML,
      };
      scope.dispose(true);
      return after;
    });
    // The mount branch must keep its own label subscription: changing the label
    // updates the slot instead of rebuilding the condition branch.
    expect(mountedAfter).toEqual({
      sameParagraph: true,
      sameText: true,
      text: 'next',
      inner:
        '<!--oe:when--><p class="on"><!--oe:t:0-->next<!--oe:/t:0--></p><!--oe:/when--><span>after</span>',
    });
    await page.close();
  });

  test('a branch top-level static run is one Text in mount, SSR, parse and claim', async () => {
    const generated = await prepare();
    const serverOpen = signal(true);
    const html = ssr(generated.loaded, 'StaticRun')({}, { bindings: { open: serverOpen } });
    expect(html).toBe('<div><!--oe:when-->AB<!--oe:/when--></div>');

    const result = (await page.evaluate(async (serverHtml) => {
      const runtime = (window as unknown as { __oeRuntime: RuntimePage }).__oeRuntime;
      const factories = (window as unknown as { __oeModule: PageModule }).__oeModule;
      document.body.innerHTML = '<div id="host"></div>';
      const host = document.getElementById('host') as HTMLElement;
      host.innerHTML = serverHtml;
      const div = host.firstChild as Element;
      const open = runtime.signal(true);
      const scope = new runtime.LifetimeScope();
      const recipe = factories.createStaticRunRecipe!(scope, {
        props: {},
        bindings: { open },
        propsChanged: runtime.signal(0),
      });
      const mutations: string[] = [];
      const observer = new MutationObserver((records) => {
        for (const record of records) mutations.push(record.type);
      });
      observer.observe(host, { subtree: true, childList: true, characterData: true });
      const projection = runtime.claimRecipe(scope, recipe, host);
      for (const record of observer.takeRecords()) mutations.push(record.type);
      const claimMutations = mutations.length;
      const claimed = {
        children: [...div.childNodes].map((node) =>
          node.nodeType === 8 ? `C:${node.nodeValue ?? ''}` : `T:${node.nodeValue ?? ''}`,
        ),
      };
      open.value = false;
      await Promise.resolve();
      await Promise.resolve();
      const empty = [...div.childNodes].map((node) =>
        node.nodeType === 8 ? `C:${node.nodeValue ?? ''}` : `T:${node.nodeValue ?? ''}`,
      );
      open.value = true;
      await Promise.resolve();
      await Promise.resolve();
      const rebuilt = [...div.childNodes].map((node) =>
        node.nodeType === 8 ? `C:${node.nodeValue ?? ''}` : `T:${node.nodeValue ?? ''}`,
      );
      observer.disconnect();
      projection.dispose(true);
      return { claimMutations, claimed, empty, rebuilt, afterDispose: host.childNodes.length };
    }, html)) as {
      claimMutations: number;
      claimed: { children: string[] };
      empty: string[];
      rebuilt: string[];
      afterDispose: number;
    };

    expect(result.claimMutations).toBe(0);
    expect(result.claimed.children).toEqual(['C:oe:when', 'T:AB', 'C:oe:/when']);
    expect(result.empty).toEqual(['C:oe:when', 'C:oe:/when']);
    expect(result.rebuilt).toEqual(['C:oe:when', 'T:AB', 'C:oe:/when']);
    expect(result.afterDispose).toBe(0);
    await page.close();
  });

  test('a shared cursor crosses a component claim and a following condition correctly', async () => {
    // M08-1b still has no SSR producer for a component reference, so this uses
    // mount-produced DOM on purpose. It proves the claim cursor is one object
    // across the child component claim and the following condition, which is
    // the part the shared-cursor path owns.
    await prepare();

    const result = (await page.evaluate(async () => {
      const runtime = (window as unknown as { __oeRuntime: RuntimePage }).__oeRuntime;
      const factories = (window as unknown as { __oeModule: PageModule }).__oeModule;
      document.body.innerHTML = '<div id="host"></div>';
      const host = document.getElementById('host') as HTMLElement;
      const open = runtime.signal(true);
      const mountScope = new runtime.LifetimeScope();
      const mountRecipe = factories.createParentRecipe!(mountScope, {
        props: {},
        bindings: { open },
        propsChanged: runtime.signal(0),
      });
      const mounted = (mountRecipe as { mount(scope: unknown): Node[] }).mount(mountScope);
      host.append(...mounted);
      // Release the mount subscriptions but keep the DOM; the claim must adopt
      // the same nodes with its own scope.
      mountScope.dispose(false);
      const div = host.firstChild as Element;
      const child = div.firstChild as Element;
      const span = child.nextSibling as Element;
      const after = span.nextSibling as Element;

      const scope = new runtime.LifetimeScope();
      const recipe = factories.createParentRecipe!(scope, {
        props: {},
        bindings: { open },
        propsChanged: runtime.signal(0),
      });
      const mutations: string[] = [];
      const observer = new MutationObserver((records) => {
        for (const record of records) mutations.push(record.type);
      });
      observer.observe(host, { subtree: true, childList: true, characterData: true });
      runtime.runtimeProbe.reset();
      let error: string | null = null;
      let projection: { dispose(detach?: boolean): void } | null = null;
      try {
        projection = runtime.claimRecipe(scope, recipe, host);
      } catch (caught) {
        error = caught instanceof Error ? caught.message : String(caught);
      }
      for (const record of observer.takeRecords()) mutations.push(record.type);
      const claimMutations = mutations.length;
      const claim = {
        childSame: div.firstChild === child,
        spanSame: child.nextSibling === span,
        afterSame: span.nextSibling === after,
        inner: div.innerHTML,
      };

      open.value = false;
      await Promise.resolve();
      await Promise.resolve();
      const off = {
        childSame: div.firstChild === child,
        spanSame: child.nextSibling === span,
        afterSame: span.nextSibling === after,
        inner: div.innerHTML,
        tags: [...div.children].map((node) => node.tagName.toLowerCase()),
      };

      open.value = true;
      await Promise.resolve();
      await Promise.resolve();
      const on = {
        childSame: div.firstChild === child,
        spanSame: child.nextSibling === span,
        afterSame: span.nextSibling === after,
        inner: div.innerHTML,
      };
      observer.disconnect();
      projection?.dispose(true);
      return { error, claimMutations, claim, off, on, afterDispose: host.childNodes.length };
    })) as {
      error: string | null;
      claimMutations: number;
      claim: { childSame: boolean; spanSame: boolean; afterSame: boolean; inner: string };
      off: {
        childSame: boolean;
        spanSame: boolean;
        afterSame: boolean;
        inner: string;
        tags: string[];
      };
      on: { childSame: boolean; spanSame: boolean; afterSame: boolean; inner: string };
      afterDispose: number;
    };

    expect(result.error).toBeNull();
    expect(result.claimMutations).toBe(0);
    expect(result.claim).toEqual({
      childSame: true,
      spanSame: true,
      afterSame: true,
      inner: '<b>child</b><span><!--oe:when--><b>on</b><!--oe:/when--></span><i>after</i>',
    });
    expect(result.off).toEqual({
      childSame: true,
      spanSame: true,
      afterSame: true,
      inner: '<b>child</b><span><!--oe:when--><i>off</i><!--oe:/when--></span><i>after</i>',
      tags: ['b', 'span', 'i'],
    });
    expect(result.on).toEqual({
      childSame: true,
      spanSame: true,
      afterSame: true,
      inner: '<b>child</b><span><!--oe:when--><b>on</b><!--oe:/when--></span><i>after</i>',
    });
    expect(result.afterDispose).toBe(0);
    await page.close();
  });

  test('a throwing branch activation surfaces the error and releases without deleting borrowed DOM', async () => {
    const generated = await prepare();
    const serverOpen = signal(true);
    const serverBoom = signal('x');
    const html = ssr(generated.loaded, 'Throwing')(
      {},
      { bindings: { open: serverOpen, boom: serverBoom } },
    );

    const result = (await page.evaluate((serverHtml) => {
      const runtime = (window as unknown as { __oeRuntime: RuntimePage }).__oeRuntime;
      const factories = (window as unknown as { __oeModule: PageModule }).__oeModule;
      document.body.innerHTML = '<div id="host"></div>';
      const host = document.getElementById('host') as HTMLElement;
      host.innerHTML = serverHtml;
      const root = host.firstChild as Element;
      const before = [...root.childNodes];
      const open = runtime.signal(true);
      const boom = {
        get value(): string {
          throw new Error('boom branch activation');
        },
      };
      const scope = new runtime.LifetimeScope();
      const recipe = factories.createThrowingRecipe!(scope, {
        props: {},
        bindings: { open, boom },
        propsChanged: runtime.signal(0),
      });
      runtime.runtimeProbe.reset();
      let error: string | null = null;
      try {
        runtime.claimRecipe(scope, recipe, host);
      } catch (caught) {
        error = caught instanceof Error ? caught.message : String(caught);
      }
      const after = runtime.runtimeProbe.snapshot();
      return {
        error,
        sameRoot: host.childNodes[0] === root,
        sameChildren:
          root.childNodes.length === before.length &&
          before.every((node, index) => root.childNodes[index] === node),
        html: host.innerHTML,
        subscriptions: after.subscriptions,
        unsubscribed: after.unsubscribed,
      };
    }, html)) as {
      error: string | null;
      sameRoot: boolean;
      sameChildren: boolean;
      html: string;
      subscriptions: number;
      unsubscribed: number;
    };

    expect(result.error).toContain('boom branch activation');
    expect(result.sameRoot).toBe(true);
    expect(result.sameChildren).toBe(true);
    expect(result.html).toContain('<p><!--oe:t:0-->x<!--oe:/t:0--></p>');
    expect(result.subscriptions).toBe(0);
    expect(result.unsubscribed).toBe(0);
    await page.close();
  });
});
